// An offline merchant API with synthetic international onboarding requests.
// Run with: go run merchant_service.go
package main

import (
	"bytes"
	"encoding/csv"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
	"sort"
	"strings"
)

type Address struct {
	City, District, StreetName, BuildingNumber, UnitName, TimeZone string
}

type Business struct {
	Sector, LegalForm string
	FoundedYear, EmployeeCount, AnnualTurnoverCents, AverageOrderCents int
	HasPhysicalStore, HasOnlineStore bool
}

type Preferences struct {
	Language, InvoiceDelivery, NotificationMode string
	HasMarketingConsent, HasServiceConsent bool
}

type Limits struct {
	SinglePaymentCents, DailyPaymentCents, RefundWindowDays, SettlementDelayDays int
}

type Capabilities struct {
	CanAcceptPayments, CanIssueRefunds, CanRequestPayouts, ShouldRequireSecondReviewer bool
}

type MerchantInput struct {
	ExternalReference, DisplayName, Country, Locale, Currency string
	ContactName, ContactRole string
	Identifiers map[string]string
	Address Address
	Business Business
	Preferences Preferences
	Limits Limits
	Capabilities Capabilities
	Tags []string
	StatementDescriptor, SupportQueue, OnboardingChannel string
}

type Verification struct {
	CardNumber, BitcoinAddress, OpenedAt, Email, Iban string
	IpAddress, MacAddress, Website, CorrelationId string
}

func (v Verification) Fields() []string {
	return []string{v.CardNumber, v.BitcoinAddress, v.OpenedAt, v.Email, v.Iban,
		v.IpAddress, v.MacAddress, v.Website, v.CorrelationId}
}

type Tenant struct {
	Slug, DisplayName, DefaultCurrency, DefaultLocale, Plan string
	EnabledCountries []string
	MonthlyDocumentLimit int
	IsExportEnabled bool
}

type Scenario struct {
	Tenant Tenant
	Verification Verification
	PaymentAmountCents, PartialRefundCents, PayoutAmountCents int
	ExpectedMerchantCount, ExpectedDocumentCount int
	Merchants []MerchantInput
}

type Merchant struct {
	Input MerchantInput
	Status string
	Reviewers map[string]bool
}

type Payment struct {
	Reference, MerchantReference, Status string
	AmountCents, RefundedCents int
}

type LedgerEntry struct {
	Reference, Account, Kind string
	AmountCents int
}

type Event struct {
	Sequence int
	Kind, Reference string
}

type Store struct {
	Tenant Tenant
	Merchants map[string]*Merchant
	Payments map[string]*Payment
	Ledger []LedgerEntry
	Events []Event
	Verification *Verification
}

func NewStore(tenant Tenant) *Store {
	return &Store{Tenant: tenant, Merchants: make(map[string]*Merchant), Payments: make(map[string]*Payment)}
}

func (s *Store) Emit(kind, reference string) {
	s.Events = append(s.Events, Event{len(s.Events) + 1, kind, reference})
}

func contains(values []string, value string) bool {
	for _, candidate := range values {
		if candidate == value { return true }
	}
	return false
}

func (s *Store) Register(input MerchantInput) error {
	if !contains(s.Tenant.EnabledCountries, input.Country) { return errors.New("unsupported country") }
	if input.ExternalReference == "" || input.DisplayName == "" { return errors.New("missing identity") }
	if _, exists := s.Merchants[input.ExternalReference]; exists { return errors.New("duplicate merchant") }
	if !input.Preferences.HasServiceConsent { return errors.New("service consent required") }
	if input.Business.EmployeeCount < 1 || input.Business.AverageOrderCents < 1 { return errors.New("invalid business") }
	if input.Limits.SinglePaymentCents > input.Limits.DailyPaymentCents { return errors.New("invalid limits") }
	if input.Address.City == "" || input.Address.TimeZone == "" { return errors.New("missing address") }
	if len(input.Tags) == 0 || input.SupportQueue == "" { return errors.New("missing routing") }
	if len(input.Identifiers) == 0 { return errors.New("documents required") }
	for _, value := range input.Identifiers {
		if strings.TrimSpace(value) == "" { return errors.New("empty document") }
	}
	// Own the map so subsequent request mutation cannot change stored documents.
	identifiers := make(map[string]string)
	for key, value := range input.Identifiers { identifiers[key] = value }
	input.Identifiers = identifiers
	input.Tags = append([]string(nil), input.Tags...)
	s.Merchants[input.ExternalReference] = &Merchant{input, "draft", make(map[string]bool)}
	s.Emit("merchant.registered", input.ExternalReference)
	return nil
}

func (s *Store) Submit(reference string) error {
	m := s.Merchants[reference]
	if m == nil || m.Status != "draft" { return errors.New("merchant is not a draft") }
	m.Status = "review"
	s.Emit("merchant.submitted", reference)
	return nil
}

func (s *Store) Approve(reference, reviewer string) error {
	m := s.Merchants[reference]
	if m == nil || m.Status != "review" { return errors.New("merchant is not under review") }
	if reviewer == "" || m.Reviewers[reviewer] { return errors.New("independent reviewer required") }
	m.Reviewers[reviewer] = true
	required := 1
	if m.Input.Capabilities.ShouldRequireSecondReviewer { required = 2 }
	if len(m.Reviewers) == required { m.Status = "active" }
	s.Emit("merchant.reviewed", reference)
	return nil
}

func (s *Store) Authorize(reference, merchantReference string, amountCents int) error {
	if previous := s.Payments[reference]; previous != nil {
		if previous.MerchantReference == merchantReference && previous.AmountCents == amountCents { return nil }
		return errors.New("idempotency conflict")
	}
	m := s.Merchants[merchantReference]
	if m == nil || m.Status != "active" || !m.Input.Capabilities.CanAcceptPayments { return errors.New("merchant cannot accept payment") }
	if amountCents < 1 || amountCents > m.Input.Limits.SinglePaymentCents { return errors.New("payment outside limits") }
	s.Payments[reference] = &Payment{Reference: reference, MerchantReference: merchantReference, Status: "authorized", AmountCents: amountCents}
	s.Emit("payment.authorized", reference)
	return nil
}

func (s *Store) Post(reference, account, kind string, amountCents int) {
	s.Ledger = append(s.Ledger, LedgerEntry{reference, account, kind, amountCents}, LedgerEntry{reference, "clearing", kind, -amountCents})
}

func (s *Store) Balance(account string) int {
	result := 0
	for _, entry := range s.Ledger { if entry.Account == account { result += entry.AmountCents } }
	return result
}

func (s *Store) Capture(reference string) error {
	p := s.Payments[reference]
	if p == nil { return errors.New("unknown payment") }
	if p.Status == "captured" { return nil }
	if p.Status != "authorized" { return errors.New("payment not authorized") }
	s.Post(reference, p.MerchantReference, "capture", p.AmountCents)
	p.Status = "captured"
	s.Emit("payment.captured", reference)
	return nil
}

func (s *Store) Refund(reference string, amountCents int) error {
	p := s.Payments[reference]
	if p == nil || p.Status != "captured" { return errors.New("payment not captured") }
	m := s.Merchants[p.MerchantReference]
	if !m.Input.Capabilities.CanIssueRefunds { return errors.New("refund disabled") }
	if amountCents < 1 || amountCents > p.AmountCents-p.RefundedCents || amountCents > s.Balance(p.MerchantReference) {
		return errors.New("refund outside available balance")
	}
	s.Post(reference, p.MerchantReference, "refund", -amountCents)
	p.RefundedCents += amountCents
	s.Emit("payment.refunded", reference)
	return nil
}

func (s *Store) Payout(reference string, amountCents int) error {
	m := s.Merchants[reference]
	if m == nil || m.Status != "active" || !m.Input.Capabilities.CanRequestPayouts { return errors.New("payout disabled") }
	if amountCents < 1 || amountCents > s.Balance(reference) { return errors.New("insufficient funds") }
	s.Post(reference, reference, "payout", -amountCents)
	s.Emit("payout.completed", reference)
	return nil
}

func (s *Store) Export() (string, error) {
	if !s.Tenant.IsExportEnabled { return "", errors.New("export disabled") }
	var output bytes.Buffer
	writer := csv.NewWriter(&output)
	_ = writer.Write([]string{"reference", "country", "city", "document", "value"})
	keys := make([]string, 0, len(s.Merchants))
	for key := range s.Merchants { keys = append(keys, key) }
	sort.Strings(keys)
	for _, key := range keys {
		input := s.Merchants[key].Input
		fields := make([]string, 0, len(input.Identifiers))
		for field := range input.Identifiers { fields = append(fields, field) }
		sort.Strings(fields)
		for _, field := range fields { _ = writer.Write([]string{key, input.Country, input.Address.City, field, input.Identifiers[field]}) }
	}
	writer.Flush()
	return output.String(), writer.Error()
}

// The adapter exercises JSON decoding and HTTP error propagation without a socket.
type API struct { Store *Store }

type Command struct {
	Reference, MerchantReference, Reviewer string
	AmountCents int
}

func (api API) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	if r.Method != http.MethodPost { http.Error(w, "method not allowed", http.StatusMethodNotAllowed); return }
	var err error
	switch r.URL.Path {
	case "/merchants":
		var input MerchantInput
		err = json.NewDecoder(r.Body).Decode(&input)
		if err == nil { err = api.Store.Register(input) }
	case "/verification":
		var input Verification
		err = json.NewDecoder(r.Body).Decode(&input)
		if err == nil {
			for _, field := range input.Fields() { if field == "" { err = errors.New("missing verification field") } }
			if err == nil { api.Store.Verification = &input }
		}
	default:
		var input Command
		err = json.NewDecoder(r.Body).Decode(&input)
		if err == nil {
			switch r.URL.Path {
			case "/submit": err = api.Store.Submit(input.Reference)
			case "/approve": err = api.Store.Approve(input.Reference, input.Reviewer)
			case "/authorize": err = api.Store.Authorize(input.Reference, input.MerchantReference, input.AmountCents)
			case "/capture": err = api.Store.Capture(input.Reference)
			case "/refund": err = api.Store.Refund(input.Reference, input.AmountCents)
			case "/payout": err = api.Store.Payout(input.Reference, input.AmountCents)
			default: http.Error(w, "unknown route", http.StatusNotFound); return
			}
		}
	}
	if err != nil { http.Error(w, err.Error(), http.StatusBadRequest); return }
	w.WriteHeader(http.StatusCreated)
	_, _ = w.Write([]byte(`{"ok":true}`))
}

type Checks struct { Assertions int }

func (c *Checks) That(ok bool, message string) {
	c.Assertions++
	if !ok { panic(message) }
}

func (c *Checks) Request(api API, path string, input any, expectedStatus int) {
	body, err := json.Marshal(input)
	if err != nil { panic(err) }
	response := httptest.NewRecorder()
	api.ServeHTTP(response, httptest.NewRequest(http.MethodPost, path, bytes.NewReader(body)))
	c.That(response.Code == expectedStatus, fmt.Sprintf("%s: %d %s", path, response.Code, response.Body.String()))
}

func RunScenario(scenario Scenario, checks *Checks) (int, int) {
	store := NewStore(scenario.Tenant)
	api := API{store}
	checks.Request(api, "/verification", scenario.Verification, http.StatusCreated)
	checks.That(*store.Verification == scenario.Verification, "verification transport changed values")
	documents := 0
	for index, input := range scenario.Merchants {
		reference := input.ExternalReference
		checks.Request(api, "/merchants", input, http.StatusCreated)
		checks.Request(api, "/merchants", input, http.StatusBadRequest)
		for field, value := range input.Identifiers {
			checks.That(store.Merchants[reference].Input.Identifiers[field] == value, "document transport changed value")
			documents++
		}
		payment := fmt.Sprintf("payment-%d", index)
		authorization := Command{Reference: payment, MerchantReference: reference, AmountCents: scenario.PaymentAmountCents}
		checks.Request(api, "/authorize", authorization, http.StatusBadRequest)
		checks.Request(api, "/submit", Command{Reference: reference}, http.StatusCreated)
		checks.Request(api, "/approve", Command{Reference: reference, Reviewer: "reviewer-a"}, http.StatusCreated)
		if input.Capabilities.ShouldRequireSecondReviewer {
			checks.That(store.Merchants[reference].Status == "review", "second review must be required")
			checks.Request(api, "/approve", Command{Reference: reference, Reviewer: "reviewer-a"}, http.StatusBadRequest)
			checks.Request(api, "/approve", Command{Reference: reference, Reviewer: "reviewer-b"}, http.StatusCreated)
		}
		checks.That(store.Merchants[reference].Status == "active", "merchant must become active")
		checks.Request(api, "/authorize", authorization, http.StatusCreated)
		checks.Request(api, "/authorize", authorization, http.StatusCreated)
		authorization.AmountCents++
		checks.Request(api, "/authorize", authorization, http.StatusBadRequest)
		checks.Request(api, "/capture", Command{Reference: payment}, http.StatusCreated)
		checks.Request(api, "/capture", Command{Reference: payment}, http.StatusCreated)
		checks.That(store.Balance(reference) == scenario.PaymentAmountCents, "capture must be idempotent")
		checks.Request(api, "/refund", Command{Reference: payment, AmountCents: scenario.PartialRefundCents}, http.StatusCreated)
		checks.Request(api, "/payout", Command{Reference: reference, AmountCents: scenario.PayoutAmountCents}, http.StatusCreated)
		balance := scenario.PaymentAmountCents - scenario.PartialRefundCents - scenario.PayoutAmountCents
		checks.That(store.Balance(reference) == balance, "incorrect merchant balance")
		checks.Request(api, "/payout", Command{Reference: reference, AmountCents: balance + 1}, http.StatusBadRequest)
		checks.That(store.Balance(reference) == balance, "failed payout mutated balance")
	}
	checks.That(documents == scenario.ExpectedDocumentCount, "missing documents")
	checks.That(len(store.Merchants) == scenario.ExpectedMerchantCount, "missing merchants")
	balanced := 0
	for _, entry := range store.Ledger { balanced += entry.AmountCents }
	checks.That(balanced == 0, "unbalanced ledger")
	export, err := store.Export()
	checks.That(err == nil, "export failed")
	rows, err := csv.NewReader(strings.NewReader(export)).ReadAll()
	checks.That(err == nil && len(rows) == documents + 1, "export lost documents")
	for _, input := range scenario.Merchants {
		for _, value := range input.Identifiers { checks.That(strings.Contains(export, value), "export changed document") }
	}
	for index, event := range store.Events { checks.That(event.Sequence == index + 1, "event ordering changed") }
	checks.Request(api, "/unknown", Command{}, http.StatusNotFound)
	return len(store.Merchants), documents
}

func main() {
	// Ordinary numeric settings are intentional negative controls for redaction.
	timeoutMs, batchSize, checksumAlgorithm := 10000, 5000, "sha256"
	checks := &Checks{}
	checks.That(timeoutMs > batchSize && checksumAlgorithm == "sha256", "configuration changed")
	merchants, documents := 0, 0
	scenarios := BuildScenarios()
	for _, scenario := range scenarios {
		merchantCount, documentCount := RunScenario(scenario, checks)
		merchants += merchantCount
		documents += documentCount
	}
	result := map[string]int{"scenarios":len(scenarios), "merchants":merchants, "documents":documents, "assertions":checks.Assertions}
	if err := json.NewEncoder(httpOutput{}).Encode(result); err != nil { panic(err) }
}

// Keep report output separate from the HTTP response writer used above.
type httpOutput struct{}
func (httpOutput) Write(data []byte) (int, error) { return fmt.Print(string(data)) }

